/// <summary>
/// Response classes documented by the HCM REST framework status-code
/// reference: 200 OK, 201 Created, 202 Accepted (accepted for processing,
/// processing not complete), 204 No Content, 4xx client errors, 5xx server
/// errors.
/// </summary>
public enum HcmResponseKind
{
    Ok,
    Created,
    Accepted,
    NoContent,
    ClientError,
    ServerError,
}

public static class HcmStatusClassifier
{
    public static HcmResponseKind Classify(int status) => status switch
    {
        200 => HcmResponseKind.Ok,
        201 => HcmResponseKind.Created,
        202 => HcmResponseKind.Accepted,
        204 => HcmResponseKind.NoContent,
        >= 400 and <= 499 => HcmResponseKind.ClientError,
        >= 500 and <= 599 => HcmResponseKind.ServerError,
        _ => throw new ArgumentOutOfRangeException(nameof(status), status,
            "Status code is outside the documented HCM REST status set."),
    };
}
