/// <summary>One entry of a framework-version-4 error document's o:errorDetails array.</summary>
public sealed record OracleErrorEntry(string Detail, string ErrorCode, string ErrorPath);

/// <summary>
/// A structured failure from the pod: an application/vnd.oracle.adf.error+json
/// document (title, status, ordered o:errorDetails). Every detail entry is
/// preserved in order. The message carries the title and the first error
/// code; credentials never appear in exception text.
/// </summary>
public sealed class OracleRestException : Exception
{
    public int HttpStatus { get; }
    public string Title { get; }
    public string ErrorStatus { get; }
    public IReadOnlyList<OracleErrorEntry> Details { get; }

    public OracleRestException(int httpStatus, string title, string errorStatus,
        IReadOnlyList<OracleErrorEntry> details)
        : base(BuildMessage(httpStatus, title, details))
    {
        HttpStatus = httpStatus;
        Title = title;
        ErrorStatus = errorStatus;
        Details = details;
    }

    private static string BuildMessage(int httpStatus, string title, IReadOnlyList<OracleErrorEntry> details)
    {
        string headline = string.IsNullOrEmpty(title) ? "Oracle HCM request failed" : title;
        string message = $"Oracle HCM request failed with HTTP {httpStatus}: {headline}";
        if (details.Count > 0 && !string.IsNullOrEmpty(details[0].ErrorCode))
            message += $" [{details[0].ErrorCode}]";
        return message;
    }
}
"}
